<?php use App\Core\Env;use App\Core\View;$base=rtrim(Env::get('APP_URL',''),'/');?>
<div class="page-head"><div><h1>Logs API agrupados</h1><p>Errores repetidos por cuenta, endpoint y estado HTTP.</p></div><div class="page-actions"><a class="btn" href="<?= View::e($base) ?>/logs">Logs clásicos</a></div></div>
<section class="panel table-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Cuenta</th><th>Método</th><th>Endpoint</th><th>HTTP</th><th>Repeticiones</th><th>Primera vez</th><th>Última vez</th><th>Mensaje</th><th>Recomendación</th></tr></thead><tbody><?php if(!$groups):?><tr><td colspan="9"><div class="empty">No hay errores API agrupados.</div></td></tr><?php endif;?><?php foreach($groups as $g):?><tr><td><?= View::e($g['account_name']?:'—') ?></td><td><?= View::e($g['method']) ?></td><td><?= View::e($g['endpoint_path']) ?></td><td><span class="badge <?= (int)$g['http_status']>=500?'red':((int)$g['http_status']>=400?'amber':'blue') ?>"><?= View::e((string)$g['http_status']) ?></span></td><td><?= (int)$g['repetitions'] ?></td><td><?= View::e($g['first_seen_at']) ?></td><td><?= View::e($g['last_seen_at']) ?></td><td><?= View::e($g['safe_message']) ?></td><td><?= View::e($g['recommendation']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
